function output_spectrum(q1, q2, q3, q4, q5, q6)

% Parameters
timeLimits = seconds([0 900.1]); % seconds
frequencyLimits = [0 1.6]; % Hz

figure
hold on

n_reduce = 2;
FrequencyResolution = 0.01;

