% Compute spectral estimate
% Run the function call below without output arguments to plot the results
[pxx,freq] = pspectrum(q1_unnamed_ROI, ...
    'FrequencyLimits',frequencyLimits,'FrequencyResolution',FrequencyResolution);

p_db = pow2db(pxx);
freq = freq(1:n_reduce:end);
p_db = p_db(1:n_reduce:end);
plot(freq, p_db)

